#include <cstdio>

struct Fill { int sym; double px; int qty; };

// Discipline: level-checked, allocation-free logging on the hot path.
void onFill(const Fill& f, bool debugEnabled) {
    if (debugEnabled)
        std::printf("fill sym=%d px=%.2f qty=%d\n", f.sym, f.px, f.qty);
    // ... hot-path work continues, untouched by the disabled branch
}

int main() { onFill({42, 101.25, 10}, true); }
// Prints: fill sym=42 px=101.25 qty=10
// The anti-pattern: "fill sym=" + std::to_string(...) - heap-allocated
// string built on EVERY call just to be discarded by the level filter.

